function canAttendMeetings(intervals) {
  // Sweep over start/end events; an end at time t is processed before a start at t.
  const events = [];
  for (const [s, e] of intervals) { events.push([s, 1]); events.push([e, -1]); }
  events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  let running = 0;
  for (const [, delta] of events) {
    running += delta;
    if (running > 1) return false;
  }
  return true;
}

